cd /tmp && python3 - <<'EOF'
import glob,re,collections
names=collections.defaultdict(list)
for f in sorted(glob.glob('/tmp/chunks/*.v')):
    for i,l in enumerate(open(f),1):
        m=re.match(r'^(Lemma|Theorem|Definition|Fixpoint|Inductive|CoInductive|Corollary|Example)\s+([A-Za-z0-9_\']+)',l)
        if m: names[m.group(2)].append((f,i,m.group(1)))
for n,v in names.items():
    if len(v)>1: print(n, v)
EOF

cd /tmp && python3 - <<'EOF'
import glob,re
sup=set()
files=glob.glob('/workspace/*.v')+glob.glob('/workspace/subtyping/*.v')
for f in files:
    if f.endswith('Task.v'): continue
    for l in open(f):
        m=re.match(r'^(Lemma|Theorem|Definition|Fixpoint|Inductive|CoInductive|Corollary|Example)\s+([A-Za-z0-9_\']+)',l)
        if m: sup.add(m.group(2))
mine={}
for f in sorted(glob.glob('/tmp/chunks/*.v')):
    for i,l in enumerate(open(f),1):
        m=re.match(r'^(Lemma|Theorem|Definition|Fixpoint|Inductive|CoInductive|Corollary|Example)\s+([A-Za-z0-9_\']+)',l)
        if m: mine.setdefault(m.group(2),(f,i))
conf=sorted(set(mine)&sup)
for n in conf: print(n, mine[n])
print('total support names',len(sup),'mine',len(mine),'conflicts',len(conf))
EOF

